52	 *     private String lastName;
53	 *
54	 *     private int age;
55	 *
56	 *     &#64;SecureField(rolesAllowed = "admin")
57	 *     private Address address;
58	 *
59	 *     public Person() {
60	 *     }
61	 *
62	 *     public Person(String firstName, String lastName, int age, Address address) {
63	 *         this.firstName = firstName;
64	 *         this.lastName = lastName;
65	 *         this.age = age;
66	 *         this.address = address;
67	 *     }
68	 *
69	 *     // getters and setters omitted
70	 * }
71	 * }</pre>
72	 *
73	 * it generates the following {@code StdSerializer} implementation
74	 *
