76	 * public class Person$quarkusjacksonserializer extends StdSerializer {
77	 *     static final String[] address_ROLES_ALLOWED = new String[] { "admin" };
78	 *
79	 *     public Person$quarkusjacksonserializer() {
80	 *         super(Person.class);
81	 *     }
82	 *
83	 *     public void serialize(Object var1, JsonGenerator var2, SerializerProvider var3) throws IOException {
84	 *         Person var4 = (Person) var1;
85	 *         var2.writeStartObject();
86	 *         var2.writeFieldName(SerializedStrings$quarkusjacksonserializer.age);
87	 *         int var5 = var4.getAge();
88	 *         var2.writeNumber(var5);
89	 *         var2.writeFieldName(SerializedStrings$quarkusjacksonserializer.firstName);
90	 *         String var6 = var4.getFirstName();
91	 *         var2.writeString(var6);
92	 *         var2.writeFieldName(SerializedStrings$quarkusjacksonserializer.familyName);
93	 *         String var7 = var4.getLastName();
94	 *         var2.writeString(var7);
95	 *         if (JacksonMapperUtil.includeSecureField(address_ROLES_ALLOWED)) {
96	 *             var2.writeFieldName(SerializedStrings$quarkusjacksonserializer.address);
97	 *             Address var9 = var4.getAddress();
98	 *             var2.writePOJO(var9);
99	 *         }
100	 *         var2.writeEndObject();
101	 *     }
102	 * }
103	 *
104	 * public class SerializedStrings$quarkusjacksonserializer {
105	 *     static final SerializedString age = new SerializedString("age");
106	 *     static final SerializedString firstName = new SerializedString("firstName");
107	 *     static final SerializedString familyName = new SerializedString("familyName");
108	 *     static final SerializedString address = new SerializedString("address");
109	 * }
